import React, { createContext, useContext, useState, useEffect } from "react";
import { supabase } from "../config/supabaseClient";

const AuthContext = createContext(null);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
};

const ADMIN_EMAIL = "arturpereira0507@gmail.com";
const ADMIN_PASS = "Freitas0507@@";
const ADMIN_USER_ID = "f71e21cd-9382-4bed-ac9a-bcc07d87ee67";

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [hubLimit, setHubLimit] = useState(2); 

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session) {
        const isAdmin = session.user.email === ADMIN_EMAIL;
        if (isAdmin) {
          setUser({ ...session.user, role: "super-admin", plan_type: "Unlimited", status: "active" });
          setHubLimit(999);
          localStorage.setItem("kyotsu_admin", "true");
        } else {
          setUser(session.user);
        }
        fetchUserSubscription(session.user.id);
      } else {
        const adminStored = localStorage.getItem("kyotsu_admin");
        if (adminStored === "true") {
           setUser({ id: ADMIN_USER_ID, email: ADMIN_EMAIL, role: "super-admin", username: "Admin", plan_type: "Unlimited" });
           setHubLimit(999);
        } else {
           setUser(null);
           setHubLimit(2);
        }
      }
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchUserSubscription = async (userId) => {
    try {
      const { data, error } = await supabase
        .from('subscriptions')
        .select('hub_limit, plan_type, status, extra_hubs')
        .eq('user_id', userId)
        .order('created_at', { ascending: false })
        .limit(1);

      const subData = data && data.length > 0 ? data[0] : null;

      if (subData && !error) {
        let baseLimit = 1;
        if (subData.plan_type === 'Plano II') baseLimit = 2;
        if (subData.plan_type === 'Plano III') baseLimit = 3;
        
        let extra = subData.extra_hubs || 0;
        if (extra > 4) extra = 4; // Teto de segurança
        
        const calculatedLimit = baseLimit + extra;

        setUser(prev => {
          if (!prev) return null;
          const isAdmin = prev.email === ADMIN_EMAIL;
          return { 
            ...prev, 
            plan_type: isAdmin ? "Unlimited" : subData.plan_type, 
            hub_limit: isAdmin ? 999 : calculatedLimit, 
            extra_hubs: extra,
            status: isAdmin ? "active" : subData.status, 
            role: isAdmin ? "super-admin" : "user" 
          };
        });
        // Admin sempre mantém hubLimit ilimitado
        setHubLimit(prev => {
          // Checa se o user atual é admin via closure segura
          const isAdminUser = user?.email === ADMIN_EMAIL;
          if (isAdminUser) return 999;
          return subData.status === 'active' ? calculatedLimit : 0;
        });
      }
    } catch (e) {
      console.error("Erro ao buscar assinatura:", e.message);
    }
  };

  const login = async (email, password) => {
    try {
      // 1. Tenta login via Supabase Auth para TODOS os usuários (incluindo admin)
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (!error && data?.user) {
        // Login Supabase bem-sucedido
        const isAdmin = email === ADMIN_EMAIL;

        if (isAdmin) {
          setHubLimit(999);
          localStorage.setItem("kyotsu_admin", "true");
          return { success: true, status: "active" };
        }

        // Usuário regular - verificar assinatura
        const { data: subs } = await supabase
          .from('subscriptions')
          .select('status')
          .eq('user_id', data.user.id)
          .order('created_at', { ascending: false })
          .limit(1);

        const sub = subs && subs.length > 0 ? subs[0] : null;
        return { success: true, status: sub?.status || 'pending_payment' };
      }

      // 2. Supabase falhou - verificar bypass admin com credenciais hardcoded
      if (email === ADMIN_EMAIL && password === ADMIN_PASS) {
        const adminData = {
          id: ADMIN_USER_ID,
          email: ADMIN_EMAIL,
          role: "super-admin",
          username: "Admin",
          plan_type: "Unlimited",
          status: "active"
        };
        setUser(adminData);
        setHubLimit(999);
        localStorage.setItem("kyotsu_admin", "true");
        return { success: true, status: "active" };
      }

      // 3. Não é admin e Supabase falhou
      return { success: false, message: error?.message || "Credenciais inválidas" };
    } catch (error) {
      return { success: false, message: "Erro na autenticação." };
    }
  };

  const register = async (email, password, username, planType) => {
    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: { username }
        }
      });

      if (error) {
        const msg = error.message.toLowerCase();
        if (msg.includes('rate limit')) {
          return { success: false, message: "Limite de cadastros por hora atingido. Aguarde alguns minutos e tente novamente." };
        }
        if (msg.includes('already registered') || msg.includes('already been registered')) {
          return { success: false, message: "Este e-mail já possui uma conta. Tente fazer login." };
        }
        return { success: false, message: error.message };
      }

      const limits = { 'Plano I': 1, 'Plano II': 2, 'Plano III': 3 };
      await supabase.from('subscriptions').insert({
        user_id: data.user.id,
        plan_type: planType,
        hub_limit: limits[planType] || 1,
        extra_hubs: 0,
        status: 'pending_payment'
      });

      return { success: true };
    } catch (error) {
      return { success: false, message: "Erro no registro." };
    }
  };

  const logout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem("kyotsu_admin");
    setUser(null);
    setHubLimit(2);
  };

  const isAdminPortal = () => user?.role === "super-admin" || user?.email === ADMIN_EMAIL || localStorage.getItem("kyotsu_admin") === "true";

  const value = {
    user,
    loading,
    hubLimit,
    login,
    register,
    logout,
    isAdminPortal,
    isAuthenticated: !!user && (user.role === "super-admin" || user.status === "active"),
    fetchUserSubscription
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
