/**
 * Retorna a URL da API do backend.
 * Prioridade: config.js de runtime > variável de ambiente > fallback localhost
 */
export function getApiUrl() {
  // 1. Runtime config (config.js carregado no index.html)
  if (window.__KYOTSU_CONFIG__ && window.__KYOTSU_CONFIG__.API_URL) {
    return window.__KYOTSU_CONFIG__.API_URL;
  }
  // 2. Variável de ambiente (tempo de build)
  if (process.env.REACT_APP_API_URL) {
    return process.env.REACT_APP_API_URL;
  }
  // 3. Fallback local
  return "http://localhost:8000";
}
